draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // draw fruit
  ctx.fillStyle = 'red';
  ctx.beginPath();
  ctx.arc(W/2 - 100 + 20*Math.sin(t), H/2 - 50, 30, 0, 2*Math.PI);
  ctx.fill();
  ctx.stroke();

  // draw veggie
  ctx.fillStyle = 'green';
  ctx.beginPath();
  ctx.arc(W/2 + 50 + 20*Math.cos(t), H/2 - 50, 30, 0, 2*Math.PI);
  ctx.fill();
  ctx.stroke();

  // draw stick figure
  ctx.beginPath();
  ctx.arc(W/2, H/2 + 50, 20, 0, 2*Math.PI);
  ctx.fillStyle = 'black';
  ctx.fill();
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 70);
  ctx.lineTo(W/2, H/2 + 120);
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 90);
  ctx.lineTo(W/2 - 30, H/2 + 70);
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 90);
  ctx.lineTo(W/2 + 30, H/2 + 70);
  ctx.stroke();

  // draw text
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.fillStyle = 'black';
  ctx.fillText('Healthy Food', W/2, H/2 + 150 + 10*Math.sin(t));
  ctx.restore();
}
